/* Northwake — tokens (see DESIGN.md) */
:root {
  --bg: oklch(0.19 0.045 268);
  --surface: oklch(0.24 0.05 268);
  --ink: oklch(0.95 0.012 260);
  --muted: oklch(0.80 0.03 262);
  --accent: oklch(0.83 0.11 70);          /* dawn */
  --on-accent: oklch(0.19 0.045 268);
  --moon: oklch(0.78 0.08 220);           /* the hypnogram line */
  --ring: var(--ink);
  --nav-h: 4rem;

  --display: "Young Serif", Georgia, "Times New Roman", serif;
  --body: "Hanken Grotesk", system-ui, -apple-system, "Segoe UI", sans-serif;

  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  color-scheme: dark;
}

*, *::before, *::after { box-sizing: border-box; }

html {
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--nav-h) + 1rem);
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 400 1.0625rem/1.7 var(--body);
  letter-spacing: 0.005em;
  -webkit-font-smoothing: antialiased;
}

::selection { background: var(--accent); color: var(--on-accent); }

a { color: inherit; text-underline-offset: 0.2em; }

:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
  border-radius: 4px;
}

h1, h2 {
  font-family: var(--display);
  font-weight: 400;
  text-wrap: balance;
  margin: 0;
}

/* Skip link */
.skip {
  position: absolute;
  left: 1rem;
  top: -4rem;
  z-index: 30;
  padding: 0.75rem 1rem;
  background: var(--ink);
  color: var(--bg);
  border-radius: 6px;
}
.skip:focus { top: 1rem; }
main:focus { outline: none; } /* programmatic target of the skip link only */

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  min-height: 3rem;
  padding: 0 1.5rem;
  border-radius: 999px;
  background: var(--accent);
  color: var(--on-accent);
  font-weight: 600;
  text-decoration: none;
  touch-action: manipulation;
  transition: background-color 180ms var(--ease-out), transform 100ms var(--ease-out);
}
.btn:active { transform: scale(0.97); background: oklch(0.76 0.11 68); }
@media (hover: hover) {
  .btn:hover { background: oklch(0.88 0.1 75); }
}
.btn--small { min-height: 2.75rem; padding: 0 1.125rem; font-size: 0.9375rem; }

/* Frosted nav */
.nav {
  position: sticky;
  top: 0;
  z-index: 20;
  background: oklch(0.19 0.045 268 / 0.86);
  border-bottom: 1px solid oklch(0.95 0.012 260 / 0.1);
}
@supports (backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px)) {
  .nav {
    -webkit-backdrop-filter: blur(14px) saturate(140%);
    backdrop-filter: blur(14px) saturate(140%);
  }
}
@media (prefers-reduced-transparency: reduce) {
  .nav { background: var(--bg); -webkit-backdrop-filter: none; backdrop-filter: none; }
}
@media (prefers-contrast: more) {
  .nav { background: var(--bg); border-bottom-color: var(--muted); }
}
/* Short screens (landscape phones, heavy zoom): the bar would eat the viewport */
@media (max-height: 500px) {
  .nav { position: static; }
  html { scroll-padding-top: 1rem; }
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  max-width: 72rem;
  min-height: var(--nav-h);
  margin: 0 auto;
  padding: 0 clamp(1rem, 4vw, 2.5rem);
}

.wordmark {
  font-family: var(--display);
  font-size: 1.3125rem;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  margin: 0;
}

.nav__links {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0;
  padding: 0;
  list-style: none;
}
.nav__links a:not(.btn) {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  padding: 0 0.75rem;
  text-decoration: none;
  color: var(--muted);
  transition: color 180ms var(--ease-out);
}
@media (hover: hover) {
  .nav__links a:not(.btn):hover { color: var(--ink); text-decoration: underline; }
}

/* Hero */
.hero {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  display: flex;
  align-items: center;
  min-height: calc(88dvh - var(--nav-h));
  padding: clamp(4rem, 10vh, 7rem) clamp(1rem, 4vw, 2.5rem) clamp(9rem, 22vh, 13rem);
}
.hero__sky {
  position: absolute;
  inset: 0;
  z-index: -1;
  width: 100%;
  height: 100%;
}
.hero__copy {
  width: 100%;
  max-width: 72rem;
  margin: 0 auto;
}
.hero h1 {
  max-width: 14ch;
  font-size: clamp(2.5rem, 1.4rem + 5vw, 5.5rem);
  line-height: 1.04;
  letter-spacing: -0.02em;
}
.lede {
  max-width: 34rem;
  margin: 1.5rem 0 2.25rem;
  font-size: clamp(1.0625rem, 1rem + 0.4vw, 1.25rem);
  color: var(--muted);
  text-wrap: pretty;
}

/* The signature line */
.hypno {
  fill: none;
  stroke: var(--moon);
  stroke-width: 2;
  stroke-linejoin: round;
  stroke-linecap: round;
}
.hero__sky .hypno { stroke-width: 2.5; filter: drop-shadow(0 0 6px oklch(0.78 0.08 220 / 0.5)); }

@media (prefers-reduced-motion: no-preference) {
  .hypno--draw {
    stroke-dasharray: 1;
    animation: draw-night 800ms var(--ease-out) 150ms both;
  }
  @keyframes draw-night { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
}

/* Testimonials */
.stories {
  max-width: 72rem;
  margin: 0 auto;
  padding: clamp(4.5rem, 10vw, 7.5rem) clamp(1rem, 4vw, 2.5rem) clamp(4rem, 8vw, 6rem);
}
.stories h2 {
  font-size: clamp(1.875rem, 1.4rem + 1.8vw, 2.75rem);
  line-height: 1.15;
  max-width: 18ch;
  margin-bottom: clamp(2.5rem, 5vw, 3.5rem);
}
.stories__row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 17rem), 1fr));
  gap: clamp(2.5rem, 5vw, 4rem);
}
.quote { margin: 0; min-width: 0; }
.quote blockquote { margin: 0; }
.quote blockquote p {
  margin: 0;
  font-size: 1.1875rem;
  line-height: 1.6;
  text-wrap: pretty;
}
.quote figcaption {
  display: grid;
  margin-top: 1.5rem;
  line-height: 1.4;
}
.quote__name { font-weight: 600; }
.quote__role { color: var(--muted); font-size: 0.9375rem; }
.quote__night { width: 7.5rem; height: 1.5rem; margin-top: 0.75rem; }

/* Footer */
.footer { color: var(--muted); }
.footer__rule { display: block; width: 100%; height: 1.5rem; }
.footer__rule .hypno { stroke-width: 1.5; opacity: 0.7; }
.footer__inner {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.5rem 2rem;
  max-width: 72rem;
  margin: 0 auto;
  padding: 2.5rem clamp(1rem, 4vw, 2.5rem) 3rem;
}
.footer__inner p { margin: 0; }
.footer .wordmark { color: var(--ink); min-height: 0; }
.footer__legal { margin-left: auto !important; }

@media (max-width: 40rem) {
  .footer__legal { margin-left: 0 !important; width: 100%; }
}

